"use client";

import { createContext, useContext, useState, useEffect } from "react";
import { useAuth } from "@/app/context/AuthContext"; // Ensure path is correct
import { db } from "@/lib/firebase"; // Ensure path is correct
import { 
  collection, 
  doc, 
  setDoc, 
  deleteDoc, 
  onSnapshot, 
  writeBatch,
  getDocs
} from "firebase/firestore";

// Types
type CartItem = {
  id: string;
  name: string;
  price: number;
  image: string;
  quantity: number;
  restaurant?: string;
};

type CartContextType = {
  cart: CartItem[];
  cartCount: number;
  cartTotal: number;
  addToCart: (item: any) => void;
  decreaseQuantity: (id: string) => void;
  removeFromCart: (id: string) => void;
  clearCart: () => void;
};

const CartContext = createContext<CartContextType | undefined>(undefined);

export function CartProvider({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState(true);

  // --- 1. SYNC LOGIC (The Brain) ---
  useEffect(() => {
    let unsubscribe: () => void;

    const syncCart = async () => {
      if (user) {
        // SCENARIO A: User Logged In -> Use Firestore
        
        // 1. Check if we have local items to migrate (Merge Logic)
        const localCart = localStorage.getItem("hungerStationCart");
        if (localCart) {
          const parsedLocal: CartItem[] = JSON.parse(localCart);
          if (parsedLocal.length > 0) {
            console.log("🚀 Migrating local cart to Firestore...");
            const batch = writeBatch(db);
            parsedLocal.forEach(item => {
              const ref = doc(db, "users", user.uid, "cart", item.id);
              batch.set(ref, item);
            });
            await batch.commit();
            localStorage.removeItem("hungerStationCart"); // Clear local after upload
          }
        }

        // 2. Real-time Listener (Firestore)
        const cartRef = collection(db, "users", user.uid, "cart");
        unsubscribe = onSnapshot(cartRef, (snapshot) => {
          const items = snapshot.docs.map(doc => doc.data() as CartItem);
          setCart(items);
          setLoading(false);
        });

      } else {
        // SCENARIO B: Guest User -> Use LocalStorage
        const savedCart = localStorage.getItem("hungerStationCart");
        if (savedCart) {
          setCart(JSON.parse(savedCart));
        } else {
          setCart([]);
        }
        setLoading(false);
      }
    };

    syncCart();

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, [user]); // Re-run when user logs in/out

  // --- 2. ACTIONS (Hybrid) ---

  const addToCart = async (item: any) => {
    // Optimistic Update (Instant UI)
    const existing = cart.find(x => x.id === item.id);
    const newItem = existing 
      ? { ...existing, quantity: existing.quantity + 1 }
      : { ...item, quantity: 1 };

    if (user) {
      // Save to Firestore
      try {
        await setDoc(doc(db, "users", user.uid, "cart", item.id), newItem);
      } catch (e) { console.error("Firestore Add Error", e); }
    } else {
      // Save to LocalStorage
      const newCart = existing 
        ? cart.map(i => i.id === item.id ? newItem : i)
        : [...cart, newItem];
      setCart(newCart);
      localStorage.setItem("hungerStationCart", JSON.stringify(newCart));
    }
  };

  const decreaseQuantity = async (id: string) => {
    const existing = cart.find(x => x.id === id);
    if (!existing) return;

    if (user) {
      // Firestore Logic
      if (existing.quantity > 1) {
        await setDoc(doc(db, "users", user.uid, "cart", id), { ...existing, quantity: existing.quantity - 1 });
      } else {
        await deleteDoc(doc(db, "users", user.uid, "cart", id));
      }
    } else {
      // LocalStorage Logic
      let newCart;
      if (existing.quantity > 1) {
        newCart = cart.map(i => i.id === id ? { ...i, quantity: i.quantity - 1 } : i);
      } else {
        newCart = cart.filter(i => i.id !== id);
      }
      setCart(newCart);
      localStorage.setItem("hungerStationCart", JSON.stringify(newCart));
    }
  };

  const removeFromCart = async (id: string) => {
    if (user) {
      await deleteDoc(doc(db, "users", user.uid, "cart", id));
    } else {
      const newCart = cart.filter(i => i.id !== id);
      setCart(newCart);
      localStorage.setItem("hungerStationCart", JSON.stringify(newCart));
    }
  };

  const clearCart = async () => {
    if (user) {
      // Batch Delete from Firestore
      const batch = writeBatch(db);
      const snapshot = await getDocs(collection(db, "users", user.uid, "cart"));
      snapshot.docs.forEach(doc => batch.delete(doc.ref));
      await batch.commit();
      setCart([]);
    } else {
      setCart([]);
      localStorage.removeItem("hungerStationCart");
    }
  };

  // --- CALCULATIONS ---
  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const cartTotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  return (
    <CartContext.Provider
      value={{
        cart,
        cartCount,
        cartTotal,
        addToCart,
        decreaseQuantity,
        removeFromCart,
        clearCart,
      }}
    >
      {children}
    </CartContext.Provider>
  );
}

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) throw new Error("useCart must be used within CartProvider");
  return context;
};